const MES=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const ref=$now.minus({months:1});
const periodo=(MES[ref.month-1].charAt(0).toUpperCase()+MES[ref.month-1].slice(1))+'/'+ref.year;

function pages(name){ try{ return $(name).all().map(i=>i.json); }catch(e){ return []; } }
function issuesOf(name){ return pages(name).flatMap(p=>(p&&p.issues)?p.issues:[]); }
function truncated(name){ const ps=pages(name); const last=ps[ps.length-1]; return last? (last.isLast===false || (!!last.nextPageToken)) : false; }

const concluidas=issuesOf('Jira Concluidas');
const criadas=issuesOf('Jira Criadas');
const movimentadas=issuesOf('Jira Movimentadas');
const trunc = truncated('Jira Concluidas')||truncated('Jira Criadas')||truncated('Jira Movimentadas');

const cat=i=>((((i.fields||{}).status||{}).statusCategory||{}).key)||'new';
const nDone=criadas.filter(i=>cat(i)==='done').length;
const nProg=criadas.filter(i=>cat(i)==='indeterminate').length;
const nBack=criadas.filter(i=>cat(i)==='new').length;
const ddmm=iso=>{ if(!iso) return '—'; const d=String(iso).slice(0,10).split('-'); return d.length===3?d[2]+'/'+d[1]:iso; };
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

// ---- payload p/ IA ----
const slim=i=>({key:i.key, status:(((i.fields||{}).status||{}).name)||'', cat:cat(i), tipo:(((i.fields||{}).issuetype||{}).name)||'', data:ddmm(i.fields&&i.fields.resolutiondate), resumo:(i.fields&&i.fields.summary)||''});
const aiUser=JSON.stringify({
  periodo,
  metricas:{concluidas:concluidas.length, abertas_no_mes:criadas.length, abertas_break:{concluidas:nDone, em_andamento:nProg, backlog:nBack}, movimentadas:movimentadas.length},
  truncado:trunc,
  concluidas:concluidas.map(slim),
  criadas:criadas.map(slim)
});

const aiSystem=[
'Você é analista de TI. Gere um RESUMO EXECUTIVO MENSAL em HTML para e-mail (Gmail/Outlook).',
'Entrada: JSON com período, métricas e listas de issues do Jira (projeto ACXEGDP, responsável Flavio Cicato Endo).',
'REGRAS DE SAÍDA:',
'- Responda APENAS com HTML. Sem markdown, sem cercas ```, sem texto antes ou depois.',
'- 100% estilo inline (sem <style>, sem <head>/<body>). Use uma <div> container de max-width:720px, fonte Arial.',
'- Comece com <h1> "Resumo Executivo de TI — {periodo}" e uma linha de responsável/área.',
'- Tabela "Números do mês" (concluídas / abertas no mês com quebra / movimentadas).',
'- Seção "Principais entregas por frente": AGRUPE as issues por frente temática inferida dos títulos (ex: PV à vista, Seguro de Crédito/Allianz, n8n/OMIE, Infraestrutura, Dados & Relatórios, ATLAS/StockBridge/CRM, Suporte/TI ops — adapte ao que existir no mês). Itemize cada frente em <ul>: 1 linha por issue com selo de status (badge <span> colorido: verde=CONCLUÍDA, âmbar=EM ANDAMENTO, cinza=BACKLOG) + <strong>chave</strong> + descrição curta.',
'- Seção "Em aberto para o próximo mês": bullets das criadas ainda não concluídas mais relevantes.',
'- Anexo: tabela (Data | Chave | Tarefa) com todas as concluídas.',
'- Se truncado=true, inclua um aviso visível de que houve mais itens que o limite.',
'- Abra com saudação curta e feche com assinatura "Flavio — TI/Sistemas". Tom executivo, PT-BR, factual (não invente issues).'
].join('\n');

// ---- fallback HTML determinístico ----
const td='border:1px solid #dfe1e6;padding:6px 10px;';
const badge=c=>c==='done'?'<span style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;background:#e3fcef;color:#006644;">CONCLUÍDA</span>':c==='indeterminate'?'<span style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;background:#fffae6;color:#974f00;">EM ANDAMENTO</span>':'<span style="display:inline-block;padding:1px 8px;border-radius:10px;font-size:11px;font-weight:700;background:#ebecf0;color:#42526e;">BACKLOG</span>';
let rows=concluidas.map(i=>`<tr><td style="${td}">${ddmm(i.fields&&i.fields.resolutiondate)}</td><td style="${td}">${esc(i.key)}</td><td style="${td}">${esc(i.fields&&i.fields.summary)}</td></tr>`).join('');
if(!rows) rows=`<tr><td colspan="3" style="${td}">Nenhuma tarefa concluída no período.</td></tr>`;
const abertas=criadas.filter(i=>cat(i)!=='done');
let bl=abertas.map(i=>`<li style="margin-bottom:4px;">${badge(cat(i))} <strong>${esc(i.key)}</strong> — ${esc(i.fields&&i.fields.summary)}</li>`).join('')||'<li>—</li>';
const warn=trunc?'<div style="margin:12px 0;padding:10px 14px;background:#ffebe6;border-left:4px solid #bf2600;color:#bf2600;">⚠️ Houve mais itens do que o limite recuperado — relatório possivelmente incompleto.</div>':'';
const fallbackHtml=`<div style="max-width:720px;margin:0 auto;padding:24px;font-family:Arial,Helvetica,sans-serif;color:#172b4d;font-size:14px;line-height:1.55;">
<h1 style="font-size:22px;margin:0 0 4px;">Resumo Executivo de TI — ${periodo}</h1>
<p style="margin:0 0 12px;color:#6b778c;font-size:12px;">Responsável: Flavio Cicato Endo · TI/Sistemas (Jira ACXEGDP) · gerado via n8n.</p>${warn}
<table style="border-collapse:collapse;width:100%;"><tr><th style="${td}text-align:left;background:#f4f5f7;">Indicador</th><th style="${td}text-align:right;background:#f4f5f7;">Valor</th></tr>
<tr><td style="${td}">Concluídas</td><td style="${td}text-align:right;"><strong>${concluidas.length}</strong></td></tr>
<tr><td style="${td}">Abertas no mês</td><td style="${td}text-align:right;"><strong>${criadas.length}</strong> <span style="color:#6b778c;font-size:12px;">(${nDone}✓ · ${nProg}⟳ · ${nBack}⏳)</span></td></tr>
<tr><td style="${td}">Movimentadas</td><td style="${td}text-align:right;">${movimentadas.length}</td></tr></table>
<h2 style="font-size:16px;margin:20px 0 8px;border-bottom:2px solid #dfe1e6;padding-bottom:4px;">Em aberto</h2><ul style="padding-left:20px;">${bl}</ul>
<h2 style="font-size:16px;margin:20px 0 8px;border-bottom:2px solid #dfe1e6;padding-bottom:4px;">Concluídas no mês (${concluidas.length})</h2>
<table style="border-collapse:collapse;width:100%;font-size:13px;"><tr><th style="${td}text-align:left;background:#f4f5f7;">Data</th><th style="${td}text-align:left;background:#f4f5f7;">Chave</th><th style="${td}text-align:left;background:#f4f5f7;">Tarefa</th></tr>${rows}</table>
<p style="margin-top:16px;font-size:12px;color:#6b778c;">Flavio — TI/Sistemas</p></div>`;

return [{ json: { periodo, assunto:'Resumo Executivo de TI — '+periodo, aiSystem, aiUser, fallbackHtml } }];

let html;
try{
  const ai=$('IA Sintese').first().json;
  let t = ai && ai.content && ai.content[0] && ai.content[0].text;
  if(t){ t=t.trim().replace(/^```html\s*/i,'').replace(/^```\s*/,'').replace(/```$/,'').trim(); }
  // EML-22 (ACXEGDP-255): valida a ESTRUTURA da saida da IA, nao so o tamanho.
  // HTML sem titulo/secoes (resposta truncada, fora do formato ou com fence
  // markdown sobrando) cai no fallback deterministico do Preparar Dados.
  const estruturaOk = !!t
    && t.length > 200
    && /<h[12][\s>]/i.test(t)
    && /<\/(p|li|td|h[1-6])>/i.test(t)
    && !/```/.test(t);
  html = estruturaOk ? t : null;
}catch(e){ html=null; }
const prep=$('Preparar Dados').first().json;
if(!html) html=prep.fallbackHtml;
return [{ json: { assunto: prep.assunto, html } }];
